parameters.jsCode:
const results = [];
const norm = v => String(v ?? '').toLowerCase().replace(/\s+/g, ' ').trim();
const decide = s => (s >= 70 ? 'interview' : s >= 50 ? 'maybe' : 'reject');
const isStrArr = a => Array.isArray(a) && a.every(x => typeof x === 'string');

for (const item of $input.all()) {
  let ai = item.json.output ?? item.json;
  if (typeof ai === 'string') {
    try { ai = JSON.parse(ai); } catch (e) { ai = {}; }
  }

  const row = $('Get row(s) in sheet').item.json;
  const prep = $('Prepare Application').item.json;
  const errors = [];
  const warnings = [];

  // 1. Required fields
  const required = ['score', 'recommendation', 'matched_requirements', 'missing_requirements', 'strengths', 'concerns', 'interview_questions', 'topSkills'];
  for (const f of required) {
    if (ai[f] === undefined || ai[f] === null) errors.push(`Missing field: ${f}`);
  }

  // 2. Field types
  for (const f of ['strengths', 'concerns', 'topSkills']) {
    if (ai[f] != null && typeof ai[f] !== 'string') errors.push(`Field ${f} must be a string`);
  }
  for (const f of ['matched_requirements', 'missing_requirements', 'interview_questions']) {
    if (ai[f] != null && !isStrArr(ai[f])) errors.push(`Field ${f} must be an array of strings`);
  }
  if (Array.isArray(ai.interview_questions) && ai.interview_questions.length !== 3) {
    errors.push(`Expected 3 interview questions, got ${ai.interview_questions.length}`);
  }

  // 3. Score
  const score = ai.score;
  const scoreOk = typeof score === 'number' && Number.isInteger(score) && score >= 0 && score <= 100;
  if (!scoreOk) errors.push('Score must be an integer between 0 and 100');

  // 4. Recommendation
  const allowed = ['interview', 'maybe', 'reject'];
  const aiRec = norm(ai.recommendation);
  if (ai.recommendation != null && !allowed.includes(aiRec)) {
    errors.push('Recommendation must be interview, maybe or reject');
  } else if (scoreOk && aiRec && aiRec !== decide(score)) {
    warnings.push(`AI recommendation (${aiRec}) did not match score ${score}, corrected to ${decide(score)}`);
  }

  // 5. Soft checks (warnings only)
  if (ai.name && norm(ai.name) !== norm(row.name)) warnings.push('AI candidate name differs from the submitted name');
  if (ai.yearsExperience != null && (typeof ai.yearsExperience !== 'number' || ai.yearsExperience < 0)) warnings.push('yearsExperience is not a valid number');
  if (typeof ai.strengths === 'string' && ai.strengths.trim().length < 20) warnings.push('Strengths text is too short');

  const valid = errors.length === 0;
  const years = typeof ai.yearsExperience === 'number' && ai.yearsExperience >= 0 ? ai.yearsExperience : null;

  results.push({
    json: {
      appliedAt: row['apllied at?'] ?? '',
      name: row.name ?? '',
      email: row.email ?? '',
      position: row.position ?? '',
      motivation: row.motivation ?? '',
      readMethod: prep.readMethod ?? '',
      cvFileId: row['cv file id'] ?? '',
      score: scoreOk ? score : null,
      recommendation: valid ? decide(score) : 'error',
      matched_requirements: isStrArr(ai.matched_requirements) ? ai.matched_requirements : [],
      missing_requirements: isStrArr(ai.missing_requirements) ? ai.missing_requirements : [],
      strengths: typeof ai.strengths === 'string' ? ai.strengths : '',
      concerns: typeof ai.concerns === 'string' ? ai.concerns : '',
      interview_questions: isStrArr(ai.interview_questions) ? ai.interview_questions : [],
      yearsExperience: years,
      topSkills: typeof ai.topSkills === 'string' ? ai.topSkills : '',
      valid,
      problems: [...errors, ...warnings].join(' | ')
    }
  });
}

return results;

parameters.message:
={{ (() => {
const d = $('Code in JavaScript').item.json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const list = a => (a && a.length) ? `<ul style='margin:0;padding-left:20px'>${a.map(x => `<li style='margin:5px 0;font-size:14px'>${esc(x)}</li>`).join('')}</ul>` : `<p style='margin:0;color:#7b8790;font-size:13px;font-style:italic'>None listed.</p>`;
const para = s => s ? `<p style='margin:0;font-size:14px;color:#45545f'>${esc(s)}</p>` : `<p style='margin:0;color:#7b8790;font-size:13px;font-style:italic'>None.</p>`;
const color = { interview: '#1b8a5a', maybe: '#d98c00', reject: '#c0392b' }[d.recommendation] || '#183153';
const sec = (t, b) => `<div style='margin-bottom:24px'><h2 style='margin:0 0 12px;padding-bottom:8px;border-bottom:1px solid #e8edf1;color:#183153;font-size:16px'>${t}</h2>${b}</div>`;
const cell = (l, v) => `<td style='width:50%;padding:10px 12px;background:#f7f9fb;border:1px solid #edf0f3;vertical-align:top'><div style='color:#687784;font-size:11px;text-transform:uppercase'>${l}</div><div style='font-size:14px;font-weight:600'>${esc(v || 'Not provided')}</div></td>`;
const qs = (d.interview_questions || []).map((q, i) => `<div style='padding:12px 14px;margin-bottom:10px;border:1px solid #e8edf1;border-radius:6px;font-size:14px'><b>Q${i + 1}.</b> ${esc(q)}</div>`).join('');
const years = d.yearsExperience == null ? 'Not provided' : d.yearsExperience + ' years';
const summary = `<table style='width:100%;border-collapse:collapse'><tr><td style='width:120px;font-size:34px;font-weight:700;color:#183153'>${d.score ?? '—'}<span style='font-size:14px;color:#687784'>/100</span></td><td><span style='display:inline-block;padding:6px 12px;border-radius:4px;background:${color};color:#ffffff;font-size:12px;font-weight:700'>${String(d.recommendation).toUpperCase()}</span></td></tr></table>`;
const info = `<table style='width:100%;border-collapse:separate;border-spacing:6px'><tr>${cell('Candidate', d.name)}${cell('Position', d.position)}</tr><tr>${cell('Email', d.email)}${cell('Applied At', d.appliedAt)}</tr><tr>${cell('Experience', years)}${cell('Top Skills', d.topSkills)}</tr><tr>${cell('Motivation', d.motivation)}${cell('CV Read Method', d.readMethod)}</tr></table>`;
return `<div style='background:#f4f6f8;padding:24px 12px;font-family:Arial,Helvetica,sans-serif;color:#263238;line-height:1.55'><div style='max-width:800px;margin:0 auto;background:#ffffff;border:1px solid #e5e9ed;border-radius:10px;overflow:hidden'><div style='padding:24px 28px;background:#183153;color:#ffffff'><h1 style='margin:0 0 4px;font-size:22px'>Candidate Evaluation Report</h1><div style='font-size:13px;color:#d8e2ee'>Confidential · For HR Review</div></div><div style='padding:26px 28px'>` + sec('Evaluation Summary', summary) + sec('Applicant Information', info) + sec('Matched Requirements', list(d.matched_requirements)) + sec('Missing Requirements', list(d.missing_requirements)) + sec('Strengths', para(d.strengths)) + sec('Concerns', para(d.concerns)) + sec('Suggested Technical Interview Questions', qs || para('')) + (d.problems ? sec('Validation Notes', para(d.problems)) : '') + `<p style='margin:0;font-size:12px;color:#78858e'>AI-assisted preliminary assessment. Please verify the candidate's original CV and confirm technical ability in the interview before making a final decision.</p></div></div></div>`;
})() }}
